        else:
            print("Invalid input. Please enter '+' for addition, '-' for subtraction, '*' for multiplication, or '/' for division.")

def get_numbers():
    """Get two integers as input and validate them."""
    while True:
        try:
            num1 = int(input("Enter the first integer: "))
            num2 = int(input("Enter the second integer: "))
            return num1, num2
        except ValueError:
            print("Invalid input. Please enter integers.")

def perform_operation(num1, num2, operation):
    """Perform the specified operation and return the result."""
    if operation == '+':
        result = num1 + num2
    elif operation == '-':
