        result = num1 / num2
    else:
        raise ValueError("Invalid operation. Please enter '+' for addition, '-' for subtraction, '*' for multiplication, or '/' for division.")
    return result

def main():
    while True:
        operation = get_operation()
        num1, num2 = get_numbers()
        try:
            result = perform_operation(num1, num2, operation)
            print(f"{num1} {operation} {num2} = {result}")
